// #40d912 באנר «קישור ההצטרפות (מוצג פעם אחת)» на /users: есть сразу после «שמירה והזמנה», нет после F5,
// нет после подтверждённой «ביטול הזמנה», остаётся при «חזרה» / Escape в окне подтверждения.
// Кейсы: .qa/tests/company-users/CU-08, CU-09. План: specs/company-users.md (раздел 6).
// ADMIN2 (компания B, .qa/auth/admin2.json). Адреса только qa-auto-banner-…@example.com; в finally все такие
// приглашения отменяются (с подтверждением) — компания B возвращается в исходное состояние. Меняет данные → @data.
import { test, expect } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import {
  CONFIRM_CANCEL, DIALOG_BACK, PENDING, bannerLink, bannerText, cancelAllInvites, invite, openCancelDialog,
  readBannerLink, rowOf, usersHeading,
} from '../helpers/invites';

const NAME = 'QA-AUTO Banner';
const QA_ROWS = /qa-auto-banner-/;
const qaEmail = () => `qa-auto-banner-${Date.now()}-${Math.floor(Math.random() * 1000)}@example.com`;

test.use({ storageState: authState('admin2') });

test.describe('באנר קישור ההצטרפות — מסך משתמשי החברה', () => {
  test('אחרי "שמירה והזמנה" מוצג באנר עם קישור ו"העתקה", ואחרי רענון (F5) הבאנר לא חוזר #40d912 @desktop @data', async ({ page }) => {
    // CU-08
    const email = qaEmail();
    try {
      await invite(page, NAME, email);
      await expect(bannerText(page)).toBeVisible();
      const link = await readBannerLink(page);
      expect([...new URL(link).searchParams.keys()], 'ссылка — только token').toEqual(['token']);
      await expect(page.getByRole('button', { name: 'העתקה', exact: true })).toBeVisible();

      await page.reload();
      await expect(usersHeading(page)).toBeVisible();
      await expect(rowOf(page, email).first()).toContainText(PENDING);
      // «מוצג פעם אחת»: после F5 ни текста баннера, ни ссылки (מה רצוי #40d912).
      await expect(bannerText(page)).toHaveCount(0);
      await expect(bannerLink(page)).toHaveCount(0);
    } finally {
      await cancelAllInvites(page, QA_ROWS);
    }
    await expect(page.getByRole('row').filter({ hasText: QA_ROWS })).toHaveCount(0);
  });

  test('ביטול הזמנה: "חזרה" ו-Escape משאירים באנר והזמנה; אישור "ביטול ההזמנה" מסיר את הבאנר #40d912 @desktop @data', async ({ page }) => {
    // CU-09
    const email = qaEmail();
    try {
      await invite(page, NAME, email);
      const link = await readBannerLink(page);

      // «חזרה» — окно закрыто, приглашение и баннер с той же ссылкой на месте (#db7e39).
      let dialog = await openCancelDialog(page, email);
      await expect(dialog).toContainText(NAME);
      await dialog.getByRole('button', { name: DIALOG_BACK, exact: true }).click();
      await expect(dialog).toBeHidden();
      await expect(rowOf(page, email).first()).toContainText(PENDING);
      await expect(bannerLink(page).first()).toContainText(link);

      // Escape — то же.
      dialog = await openCancelDialog(page, email);
      await page.keyboard.press('Escape');
      await expect(dialog).toBeHidden();
      await expect(rowOf(page, email).first()).toContainText(PENDING);
      await expect(bannerLink(page).first()).toContainText(link);

      // Подтверждение — строки нет, баннера со ссылкой нет (מה רצוי: «נעלם … כשההזמנה שבו מבוטלת»).
      dialog = await openCancelDialog(page, email);
      await dialog.getByRole('button', { name: CONFIRM_CANCEL, exact: true }).click();
      await expect(dialog).toBeHidden();
      await expect(rowOf(page, email)).toHaveCount(0);
      await expect(bannerLink(page)).toHaveCount(0);
      await expect(bannerText(page)).toHaveCount(0);
    } finally {
      await cancelAllInvites(page, QA_ROWS);
    }
    await expect(page.getByRole('row').filter({ hasText: QA_ROWS })).toHaveCount(0);
  });
});
